problems.solution:
def cohens_kappa(a, b):
    if len(a) != len(b) or not a:
        raise ValueError("need two equal-length, non-empty label lists")
    n = len(a)
    po = sum(x == y for x, y in zip(a, b)) / n
    labels = set(a) | set(b)
    pe = sum((a.count(c) / n) * (b.count(c) / n) for c in labels)
    if pe == 1:
        return 1.0
    return (po - pe) / (1 - pe)

